                    .append(r.checkOutDate()).append(',').append(r.status()).append(',')
                    .append(r.retained().toPlainString()).append('\n');
            total = total.add(r.retained());
        }
        return csv.append("total,").append(Money.round(total).toPlainString()).append('\n').toString();
    }
}
